// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address actor, address target, uint256 value, bytes memory data) public {
        vm.assume(actor != address(0));
        vm.assume(target != address(0));
        vm.deal(actor, value);
        vm.prank(actor);
        bool ok = true;
        try c.sendMoney(target, value, data) { ok = true; } catch { ok = false; }
        assertTrue(ok == (actor == c.owner()));
    }
}
